<script setup lang="ts">
import {ref,computed} from 'vue'
import {useRouter} from 'vue-router'
import {useCatalog} from '../stores/catalog'
import {download,slug} from '../utils/common'
import type {Template} from '../types'
const s=useCatalog(),router=useRouter(),active=ref<string|null>(null)
const draft=ref<Template>({id:'',name:'',desc:'',content:'',builtIn:false,enabled:true})
const editing=computed(()=>active.value!==null)
function edit(t?:Template){draft.value=t?structuredClone(t):{id:crypto.randomUUID(),name:'',desc:'',content:'# {{api.name}}\n\n{{api.description}}\n\n## Operations\n{{api.operations}}',builtIn:false,enabled:true};active.value=t?.id||'new'}
function save(){if(!draft.value.name.trim()||!draft.value.content.trim()){window.alert('Template name and content are required');return}if(draft.value.builtIn){draft.value.id=crypto.randomUUID();draft.value.builtIn=false;draft.value.name+=' (custom)'}const index=s.templates.findIndex(t=>t.id===draft.value.id);if(index>=0)s.templates[index]=structuredClone(draft.value);else s.templates.push(structuredClone(draft.value));active.value=null}
function remove(t:Template){if(t.builtIn)return;if(window.confirm('Delete '+t.name+'?'))s.templates=s.templates.filter(x=>x.id!==t.id)}
function importJson(ev:Event){const f=(ev.target as HTMLInputElement).files?.[0];if(!f)return;f.text().then(txt=>{try{const o=JSON.parse(txt) as Partial<Template>;if(typeof o.name!=='string'||typeof o.content!=='string')throw Error('Expected name and content');s.templates.push({id:crypto.randomUUID(),name:o.name,desc:String(o.desc||''),content:o.content,builtIn:false,enabled:true})}catch{window.alert('Invalid JSON template')}})}
</script><template><template v-if="s.settings.role!=='admin'"><h1>Administrator access (demo)</h1><p class="sub">Switch the demo role to Admin to manage TDD templates.</p><button class="btn" @click="router.push('/docs')">Open docs</button></template><template v-else><h1>TDD Template Administration</h1><p class="sub">Manage Markdown-based technical design templates. Admin role here is only a UI demo setting, not secure authorization.</p><div v-if="!editing"><div class="toolbar"><button class="btn" @click="edit()">+ New template</button><label class="btn ghost sm clickable">Import JSON <input type="file" accept="application/json" style="display:none" @change="importJson"/></label></div><div class="grid tplg"><div v-for="t in s.templates" :key="t.id" class="card tplc"><div class="tplc-h"><h2>{{t.name}}</h2><span class="tag" :class="t.enabled?'ok':'wn'">{{t.enabled?'Enabled':'Hidden'}}</span></div><p class="mu">{{t.desc}}</p><p class="small">{{t.builtIn?'Built-in template':'Custom template'}}</p><div class="actions tpl-act"><button class="btn ghost sm" @click="edit(t)">{{t.builtIn?'Duplicate / edit':'Edit'}}</button><button class="btn ghost sm" @click="t.enabled=!t.enabled">{{t.enabled?'Hide':'Enable'}}</button><button class="btn ghost sm" @click="download(`template-${slug(t.name)}.json`,JSON.stringify(t,null,2),'application/json')">Export</button><button v-if="!t.builtIn" class="btn ghost sm danger" @click="remove(t)">Delete</button></div></div></div></div><div v-else class="card"><h2>Template editor</h2><label>Name</label><input v-model="draft.name"/><label>Description</label><textarea v-model="draft.desc"/><label>Markdown body</label><textarea v-model="draft.content" rows="18" class="mono"/><div class="note mt">Placeholders: <code v-pre>{{api.name}}, {{api.version}}, {{api.description}}, {{api.backend}}, {{api.suffix}}, {{api.team}}, {{api.auth}}, {{api.operations}}</code></div><div class="actions"><button class="btn" @click="save">Save template</button><button class="btn ghost" @click="active=null">Cancel</button></div></div></template></template>
